    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    bool cards[6][6] = {};
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;

        int color = 0;
        if (s[0] == 'R') color = 1;
        else if (s[0] == 'G') color = 2;
        else if (s[0] == 'B') color = 3;
        else if (s[0] == 'Y') color = 4;
        else if (s[0] == 'W') color = 5;

        cards[color][s[1] - '0'] = true;
    }

    int answer = 10;

    for (int mask = 0; mask < (1 << 10); ++mask) {
        bool selectedColor[6] = {};
        bool selectedNumber[6] = {};
        bool remaining[6][6] = {};
        int count = 0;

        for (int i = 1; i <= 5; ++i) {
            selectedColor[i] = (mask & (1 << (i - 1))) != 0;
            selectedNumber[i] = (mask & (1 << (i + 4))) != 0;

            for (int j = 1; j <= 5; ++j) {
                remaining[i][j] = cards[i][j];
                if (remaining[i][j]) ++count;
            }
        }

        for (int i = 1; i <= 5; ++i) {
            for (int j = 1; j <= 5; ++j) {
                if (remaining[i][j] &&
                    selectedColor[i] && selectedNumber[j]) {
                    remaining[i][j] = false;
                    --count;
                }
            }
        }

        bool changed;
        do {
            changed = false;

            for (int color = 1; color <= 5; ++color) {
                if (!selectedColor[color]) continue;

                int onlyNumber = 0;
                int occurrences = 0;

                for (int number = 1; number <= 5; ++number) {
                    if (remaining[color][number]) {
                        onlyNumber = number;
                        ++occurrences;
                    }
                }

                if (occurrences == 1) {
                    remaining[color][onlyNumber] = false;
                    --count;
                    changed = true;
                }
            }

            for (int number = 1; number <= 5; ++number) {
                if (!selectedNumber[number]) continue;

                int onlyColor = 0;
                int occurrences = 0;

                for (int color = 1; color <= 5; ++color) {
                    if (remaining[color][number]) {
                        onlyColor = color;
                        ++occurrences;
                    }
                }

                if (occurrences == 1) {
                    remaining[onlyColor][number] = false;
                    --count;
                    changed = true;
                }
            }
        } while (changed);

        if (count < 2) {
            answer = min(answer, __builtin_popcount(static_cast<unsigned>(mask)));
        }
    }

    cout << answer << '\n';
    return 0;
}

